import{_ as t,o as h,c as a,a3 as o}from"./chunks/framework.DX_KL3e0.js";const p=JSON.parse('{"title":"Câu hỏi thường gặp (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"phu-luc/faq.md","filePath":"phu-luc/faq.md","lastUpdated":1782143716000}'),g={name:"phu-luc/faq.md"};function i(r,n,c,e,s,u){return h(),a("div",null,[...n[0]||(n[0]=[o('<h1 id="cau-hoi-thuong-gap-faq" tabindex="-1">Câu hỏi thường gặp (FAQ) <a class="header-anchor" href="#cau-hoi-thuong-gap-faq" aria-label="Permalink to &quot;Câu hỏi thường gặp (FAQ)&quot;">​</a></h1><p>Tổng hợp các câu hỏi phổ biến khi sử dụng FADO AssetFlow. Nếu gặp sự cố cụ thể, xem thêm <a href="/help/phu-luc/xu-ly-su-co.html">Xử lý sự cố</a>.</p><h2 id="đang-nhap-tai-khoan" tabindex="-1">Đăng nhập &amp; tài khoản <a class="header-anchor" href="#đang-nhap-tai-khoan" aria-label="Permalink to &quot;Đăng nhập &amp; tài khoản&quot;">​</a></h2><p><strong>Tôi quên mật khẩu, làm sao lấy lại?</strong> Trên màn hình đăng nhập, nhấn <strong>&quot;Quên mật khẩu?&quot;</strong>, nhập email công ty. Bạn sẽ nhận email chứa link đặt lại mật khẩu (có hạn 24 giờ).</p><p><strong>Tôi không đăng nhập được dù nhập đúng mật khẩu?</strong> Có thể tài khoản bị khóa (<code>status</code> không phải <code>active</code>) hoặc email gõ sai. Liên hệ Admin để kiểm tra trạng thái tài khoản.</p><p><strong>Làm sao đổi mật khẩu khi đang đăng nhập?</strong> Vào <strong>Hồ sơ cá nhân</strong> và chọn đổi mật khẩu.</p><h2 id="quyen-menu" tabindex="-1">Quyền &amp; menu <a class="header-anchor" href="#quyen-menu" aria-label="Permalink to &quot;Quyền &amp; menu&quot;">​</a></h2><p><strong>Vì sao tôi không thấy một số menu/module?</strong> Hệ thống phân quyền theo <strong>vai trò</strong> (RBAC). Mỗi vai trò chỉ thấy các module được cấp quyền. Nếu cần truy cập một chức năng, đề nghị Admin/Super Admin cấp quyền cho vai trò của bạn. Xem <a href="/help/bat-dau/phan-quyen.html">Phân quyền</a>.</p><p><strong>Có những vai trò nào?</strong> Bốn vai trò chính: <strong>Super Admin</strong>, <strong>Admin</strong>, <strong>Quản lý</strong>, <strong>Người dùng</strong>. Quyền chi tiết được cấp theo từng module.</p><p><strong>Cấu hình Ticket nằm ở đâu, sao tôi (Admin) không vào được?</strong> Lối vào <strong>Cấu hình Ticket</strong> (<code>/tickets/admin/config</code>) chỉ hiển thị với <strong>Super Admin</strong>. Admin thường không thấy mục này theo thiết kế.</p><h2 id="cham-cong" tabindex="-1">Chấm công <a class="header-anchor" href="#cham-cong" aria-label="Permalink to &quot;Chấm công&quot;">​</a></h2><p><strong>Tôi đã điểm danh trên máy nhưng bảng công không hiển thị?</strong> Thường do mã chấm công (PIN) trên máy chưa được khớp với hồ sơ của bạn. Báo Admin <strong>gán mã</strong> hoặc cập nhật <strong>Mã nhân viên</strong> cho trùng PIN.</p><p><strong>Giờ vào/ra hiển thị sai?</strong> Kiểm tra <strong>múi giờ trên máy chấm công</strong> đã đặt GMT+7 chưa (báo IT).</p><p><strong>Bù công, tăng ca khác nhau thế nào?</strong><strong>Bù công</strong> là khai báo cho lần quên/lỗi chấm công (ví dụ quên vân tay). <strong>Tăng ca</strong> là thời gian làm thêm ngoài ca chuẩn. Xem <a href="/help/phu-luc/thuat-ngu.html">Thuật ngữ</a>.</p><h2 id="ticket-cong-viec" tabindex="-1">Ticket &amp; công việc <a class="header-anchor" href="#ticket-cong-viec" aria-label="Permalink to &quot;Ticket &amp; công việc&quot;">​</a></h2><p><strong>Ticket và Task khác gì nhau?</strong><strong>Ticket</strong> là yêu cầu hỗ trợ / tác vụ nội bộ toàn doanh nghiệp. <strong>Task (Công việc)</strong> là đầu việc được giao và theo dõi tiến độ. Cả hai đều có thể gửi thông báo cập nhật qua Telegram.</p><p><strong>Tôi có nhận được thông báo khi ticket/task thay đổi không?</strong> Có — trong ứng dụng, và qua <strong>Telegram</strong> nếu bạn đã liên kết.</p><h2 id="thong-bao" tabindex="-1">Thông báo <a class="header-anchor" href="#thong-bao" aria-label="Permalink to &quot;Thông báo&quot;">​</a></h2><p><strong>Làm sao nhận thông báo qua Telegram?</strong> Liên kết <strong>Telegram Chat ID</strong> trong hồ sơ cá nhân.</p><p><strong>Tôi không nhận được email/thông báo?</strong> Xem <a href="/help/phu-luc/xu-ly-su-co.html">Xử lý sự cố</a>.</p><h2 id="tep-đinh-kem" tabindex="-1">Tệp đính kèm <a class="header-anchor" href="#tep-đinh-kem" aria-label="Permalink to &quot;Tệp đính kèm&quot;">​</a></h2><p><strong>Tải ảnh/tệp lên bị lỗi?</strong> Kiểm tra dung lượng và định dạng tệp; thử lại với mạng ổn định. Nếu vẫn lỗi, báo IT. Xem <a href="/help/phu-luc/xu-ly-su-co.html">Xử lý sự cố</a>.</p>',22)])])}const l=t(g,[["render",i]]);export{p as __pageData,l as default};
